import {routePoint,paintRouteLine} from './route-motion.js?v=motion-v70';
import {paintTextureFill} from './texture-fill.js?v=motion-v70';
import {paintFire,paintCloudVeil,cloudTravelProgress,effectMedia} from './reveal-fx.js?v=motion-v70';
const clamp=q=>Math.max(0,Math.min(1,q));
export const effectDefinitions=[
 {id:'texture-fill',label:'Fill silhouette with image or color',compatible:['image','video','text'],defaults:{mode:'image',color:'#d8f7ff',textureSlot:'titleTexture',speed:16,scale:1,opacity:1}},
 {id:'route-travel',label:'Travel along a route',compatible:['image','video','scene3d','text'],defaults:{duration:4,endScale:.2,points:[[.25,.7],[.5,.4],[.75,.2]],lineStyle:'dashed',color:'#75c6e5'}},
 {id:'cloud-descent',label:'Descend through clouds',compatible:['image','video','scene3d','text'],defaults:{duration:3,strength:1,direction:'up'}},
 {id:'fire-frame',label:'Fire around image',compatible:['image','video','scene3d','text'],defaults:{strength:.5}},
 {id:'light-pulse',label:'Light swell',compatible:['image','video','scene3d','text'],defaults:{strength:.25,speed:1,color:'#d3e7ff'}},
 {id:'lightning',label:'Lightning flash',compatible:['image','video','scene3d','text'],defaults:{strength:.5,speed:1,color:'#e3eeff'}},
 {id:'vignette',label:'Edge shadows',compatible:['image','video','scene3d','text'],defaults:{strength:.3}},
 {id:'soft-focus',label:'Soft focus',compatible:['image','video','scene3d','text'],defaults:{strength:2}},
 {id:'fade-in',label:'Fade entrance',compatible:['image','video','scene3d','text'],defaults:{duration:1}},
 {id:'push-in',label:'Camera push',compatible:['image','video','scene3d','text'],defaults:{strength:.06,duration:3}}
];
export function compatibleEffects(kind,presets=[]){return [...effectDefinitions,...presets].filter(e=>(e.compatible||['image','video']).includes(kind))}
export function instantiateEffect(definition){return {id:definition.id,type:definition.type||definition.id,enabled:true,...structuredClone(definition.defaults||{})}}
export function effectStack(source,settings={}){return source?settings.assetEffectBindings?.[source._assetId]||[]:[]}
export function paintEffects(c,stack,time,rect,paint){const [x,y,w,h]=rect;c.save();let filters=c.filter&&c.filter!=='none'?[c.filter]:[];for(const effect of stack){if(effect.enabled===false)continue;switch(effect.type||effect.id){case 'route-travel':{const q=clamp(time/Math.max(.1,effect.duration||4)),p=routePoint(effect.points||[[.5,.5],[.5,.5]],q);paintRouteLine(c,(effect.points||[]).map(p=>[(x+p[0]*w)/960,(y+p[1]*h)/540]),q,{color:effect.color,style:effect.lineStyle||'dashed'});c.translate((p[0]-.5)*w,(p[1]-.5)*h);c.translate(x+w/2,y+h/2);const z=1+((effect.endScale??.2)-1)*q;c.scale(z,z);c.translate(-x-w/2,-y-h/2);break}case 'cloud-descent':break;case 'soft-focus':filters.push(`blur(${Math.max(0,Math.min(30,effect.strength??2))}px)`);break;case 'fade-in':c.globalAlpha*=clamp(time/Math.max(.01,effect.duration||1));break;case 'push-in':{const z=1+(effect.strength??.06)*clamp(time/Math.max(.01,effect.duration||3));c.translate(x+w/2,y+h/2);c.scale(z,z);c.translate(-x-w/2,-y-h/2);break}}}if(filters.length)c.filter=filters.join(' ');paint();c.filter='none';c.beginPath();c.rect(x,y,w,h);c.clip();for(const effect of stack){if(effect.enabled===false)continue;const type=effect.type||effect.id;if(type==='fire-frame'){paintFire(c,time,rect,effect.strength??.5)}else if(type==='cloud-descent'){const p=clamp(time/Math.max(.1,effect.duration||3));c.save();c.translate(x,y);c.scale(w/960,h/540);paintCloudVeil(c,time,cloudTravelProgress(p,effect.direction),{direction:effect.direction||'up',opacity:effect.strength??1,brightness:1-.55*Math.sin(Math.PI*p)});c.restore()}else if(type==='vignette'){c.save();const g=c.createRadialGradient(x+w/2,y+h/2,Math.min(w,h)*.15,x+w/2,y+h/2,Math.max(w,h)*.65);g.addColorStop(0,'#0000');g.addColorStop(1,`rgba(0,0,0,${clamp(effect.strength??.3)})`);c.fillStyle=g;c.fillRect(x,y,w,h);c.restore()}else if(type==='light-pulse'||type==='lightning'){c.save();c.globalCompositeOperation='screen';const phase=time*Math.max(.05,effect.speed||1),pulse=type==='lightning'?Math.pow(Math.max(0,Math.sin(phase*6.283+.43*Math.sin(phase*3.1))),30):.5-.5*Math.cos(phase*3.14159);c.globalAlpha*=pulse*clamp(effect.strength??.25);c.fillStyle=effect.color||'#d3e7ff';c.fillRect(x,y,w,h);c.restore()}}c.restore()}
export function drawAssetMedia(c,source,rect,settings={},time=0){const stack=effectStack(source,settings);if(!stack.length){c.drawImage(source,...rect);return}const fill=stack.find(e=>(e.type||e.id)==='texture-fill'&&e.enabled!==false);paintEffects(c,stack,time,rect,()=>fill?paintTextureFill(c,b=>b.drawImage(source,...rect),rect,effectMedia(fill.textureSlot||'titleTexture')||effectMedia('precisionClouds'),fill,time):c.drawImage(source,...rect))}
export function buildAnimationPrompt({label='the supplied image',goal='a subtle, context-appropriate gesture',moving='only the smallest region needed for that gesture',locked='all other regions, identity, face, body silhouette and background',seconds=3,camera='locked camera',strength='subtle'}={}){return `Animate ${label} for ${Math.max(.5,Math.min(30,Number(seconds)||3))} seconds. First inspect the source and identify its subjects, contact points, depth and materials. Requested motion: ${goal}. Moving region: ${moving}. Keep fixed: ${locked}. Camera: ${camera}. Motion intensity: ${strength}. Preserve the original composition, aspect ratio, object count, proportions, textures and lighting unless the requested effect explicitly changes them. Maintain natural contact and occlusion; animate only physically necessary adjacent fabric, shadows or reflections. Use a gentle onset and hold the final pose. Do not introduce new objects, text, body drift, facial changes, camera movement, cutout gaps, stretching, temporal flicker or background warping. If the requested movement conflicts with a protected region, reduce the movement rather than distort that region. Return a clean, temporally consistent clip; no music, sound, captions or watermark.`}
